cat > ReadBinlog.cs << 'CSEOF'
using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
        var build = BinaryLog.ReadBuild(binlogPath);

        // Collect all errors
        var errors = new List<(string Project, string Code, string Message, string File, int Line)>();
        var warnings = new List<(string Project, string Code, string Message, string File)>();

        build.VisitAllChildren<Error>(e =>
        {
            var project = GetParentProject(e);
            errors.Add((project, e.Code ?? "", e.Text ?? e.ToString(), e.File ?? "", e.LineNumber));
        });

        build.VisitAllChildren<Warning>(w =>
        {
            var project = GetParentProject(w);
            warnings.Add((project, w.Code ?? "", w.Text ?? w.ToString(), w.File ?? ""));
        });

        Console.WriteLine("=== BUILD ERRORS ===");
        Console.WriteLine($"Total errors: {errors.Count}");
        Console.WriteLine();

        var groupedByProject = errors.GroupBy(e => e.Project).OrderBy(g => g.Key);
        foreach (var group in groupedByProject)
        {
            Console.WriteLine($"--- Project: {group.Key} ---");
            foreach (var err in group)
            {
                Console.WriteLine($"  [{err.Code}] {err.File}({err.Line}): {err.Message}");
            }
            Console.WriteLine();
        }

        // Check for project build failures (MSB4181, etc.)
        Console.WriteLine("=== FAILED PROJECTS ===");
        build.VisitAllChildren<Project>(p =>
        {
            if (!p.Succeeded)
            {
                Console.WriteLine($"  FAILED: {p.Name} (target: {p.TargetFramework})");
            }
        });
        Console.WriteLine();

        // Show relevant warnings
        var relevantWarnings = warnings.Where(w =>
            w.Code.StartsWith("CS") || w.Code.StartsWith("MSB") || w.Code.StartsWith("NU"))
            .Take(30);
        if (relevantWarnings.Any())
        {
            Console.WriteLine("=== RELEVANT WARNINGS (first 30) ===");
            foreach (var w in relevantWarnings)
            {
                Console.WriteLine($"  [{w.Code}] {w.Project}: {w.Message}");
            }
        }
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p) return p.Name ?? "(unknown)";
            if (current is Target t && t.Parent is Project tp) return tp.Name ?? "(unknown)";
            current = current.Parent;
        }
        return "(unknown)";
    }
}
