using System;
using System.Collections.Generic;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program2
{
    static void Main(string[] args)
    {
        var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
        var build = BinaryLog.ReadBuild(binlogPath);

        // Get all project evaluations and their references
        Console.WriteLine("=== PROJECT STRUCTURE ===");
        build.VisitAllChildren<Project>(p =>
        {
            Console.WriteLine($"Project: {p.Name} | ProjectFile: {p.ProjectFile}");
        });

        Console.WriteLine();
        Console.WriteLine("=== ALL MESSAGES WITH 'Newtonsoft' ===");
        build.VisitAllChildren<Message>(m =>
        {
            if (m.Text != null && m.Text.Contains("Newtonsoft", StringComparison.OrdinalIgnoreCase))
                Console.WriteLine($"  {m.Text.Substring(0, Math.Min(m.Text.Length, 200))}");
        });

        Console.WriteLine();
        Console.WriteLine("=== NUGET RESTORE MESSAGES ===");
        build.VisitAllChildren<Message>(m =>
        {
            if (m.Text != null && (m.Text.Contains("NU1") || m.Text.Contains("restore", StringComparison.OrdinalIgnoreCase) && m.Text.Contains("fail", StringComparison.OrdinalIgnoreCase)))
                Console.WriteLine($"  {m.Text.Substring(0, Math.Min(m.Text.Length, 300))}");
        });

        Console.WriteLine();
        Console.WriteLine("=== NUGET WARNINGS ===");
        build.VisitAllChildren<Warning>(w =>
        {
            if (w.Code != null && w.Code.StartsWith("NU"))
                Console.WriteLine($"  [{w.Code}] {w.Text}");
        });

        Console.WriteLine();
        Console.WriteLine("=== PACKAGE REFERENCES IN Services.csproj ===");
        build.VisitAllChildren<AddItem>(a =>
        {
            var proj = GetParentProject(a);
            if (proj.Contains("Services"))
            {
                if (a.Name == "PackageReference" || a.Name == "Reference")
                    Console.WriteLine($"  {a.Name}: {string.Join(", ", a.Children.Select(c => c.ToString()))}");
            }
        });

        // Also look at item groups
        Console.WriteLine();
        Console.WriteLine("=== ITEMS IN Services.csproj ===");
        build.VisitAllChildren<Item>(item =>
        {
            var proj = GetParentProject(item);
            if (proj.Contains("Services") && item.Name != null && 
                (item.Name.Contains("Reference") || item.Name.Contains("Package")))
            {
                Console.WriteLine($"  {item.Name}: {item.Text}");
            }
        });
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p) return p.Name ?? "(unknown)";
            current = current.Parent;
        }
        return "(unknown)";
    }
}
