using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program2
{
    static void Main(string[] args)
    {
        var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
        var build = BinaryLog.ReadBuild(binlogPath);

        string[] filesToDump = {
            "BuildDiag.sln",
            "Core/Core.csproj",
            "Api/Api.csproj",
            "Services/Services.csproj",
        };

        var sourceFiles = build.SourceFiles;
        foreach (var sf in sourceFiles)
        {
            foreach (var target in filesToDump)
            {
                if (sf.FullPath.EndsWith(target))
                {
                    Console.WriteLine($"=== {target} ===");
                    Console.WriteLine(sf.Text);
                    Console.WriteLine();
                }
            }
        }

        // Also dump the source files mentioned in errors
        Console.WriteLine("=== Services/UserService.cs (from error context) ===");
        // Look for it in messages or embedded files
        foreach (var sf in sourceFiles)
        {
            if (sf.FullPath.Contains("UserService") || sf.FullPath.Contains("Services/") && sf.FullPath.EndsWith(".cs"))
            {
                Console.WriteLine($"Found: {sf.FullPath}");
                Console.WriteLine(sf.Text);
            }
        }

        // Dump assets for Services
        Console.WriteLine();
        Console.WriteLine("=== Services/obj/project.assets.json (packages section) ===");
        foreach (var sf in sourceFiles)
        {
            if (sf.FullPath.Contains("Services") && sf.FullPath.Contains("project.assets.json"))
            {
                // Just show first 2000 chars
                var text = sf.Text;
                if (text.Length > 3000) text = text.Substring(0, 3000) + "\n... (truncated)";
                Console.WriteLine(text);
            }
        }
    }
}
