using System;
using Microsoft.Build.Logging.StructuredLogger;

class Program2
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild("build.binlog");

        Console.WriteLine("=== ALL ERRORS (with project context) ===");
        build.VisitAllChildren<Error>(e =>
        {
            var proj = GetProject(e);
            Console.WriteLine($"  Project={proj} [{e.Code}] {e.File}({e.LineNumber}): {e.Text}");
        });

        Console.WriteLine();
        Console.WriteLine("=== PROJECT BUILD RESULTS ===");
        build.VisitAllChildren<Project>(p =>
        {
            // Check if project has any child errors
            bool hasErrors = false;
            p.VisitAllChildren<Error>(e => hasErrors = true);
            if (hasErrors || p.FindChild<Target>() != null)
            {
                // just print the project
            }
        });

        // Check for MSB3202 or dependency errors
        Console.WriteLine("=== DEPENDENCY-RELATED MESSAGES ===");
        build.VisitAllChildren<Message>(m =>
        {
            if (m.Text != null && (m.Text.Contains("MSB3202") || m.Text.Contains("could not be resolved") || 
                m.Text.Contains("referenced by") || m.Text.Contains("dependency")))
                Console.WriteLine($"  {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");
        });

        // Check warnings for cascading
        Console.WriteLine();
        Console.WriteLine("=== MSB WARNINGS ===");
        build.VisitAllChildren<Warning>(w =>
        {
            if (w.Code != null && (w.Code.StartsWith("MSB") || w.Code == "CS0012"))
                Console.WriteLine($"  [{w.Code}] Project={GetProject(w)}: {w.Text}");
        });
    }

    static string GetProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p) return p.Name ?? "?";
            current = current.Parent;
        }
        return "?";
    }
}
